import os
from rich.console import Console
from io import StringIO

def test_broken_pipe():
    r, w = os.pipe()
    os.close(r)
    # Use a Console that writes to the write-end of the pipe
    # We need to wrap w in something that has a .write() and .flush() method
    # os.fdopen creates a file object from the file descriptor
    with os.fdopen(w, 'w') as f:
        console = Console(file=f, force_terminal=False)
        try:
            # Write a lot of data to ensure it hits the buffer check and writes
            for i in range(1000):
                console.print(f"Line {i}")
        except BrokenPipeError:
            print("Caught BrokenPipeError - Test Failed")
        except Exception as e:
            print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        else:
            print("Successfully handled BrokenPipeError or didn't encounter one")

if __name__ == "__main__":
    test_broken_pipe()

